  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 3: DC motors and the Arduino Uno$t$,$t$Connect the DC motors through the motor driver and test that they spin.$t$,3) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$How the motor driver works$t$,$t$<p><strong>🎯 Objective:</strong> Explain why the motors connect through a motor driver.</p><p>An Arduino pin cannot supply enough power to run a motor. The <strong>motor driver</strong> sits in between. The Arduino sends it small control signals, and the driver uses the motor battery to spin the motors, controlling their <strong>speed and direction</strong>.</p><h3>You need</h3><ul><li>DC motor</li><li>Arduino Uno</li><li>Motor driver</li><li>Jumper wires</li><li>Chassis</li><li>USB cable</li><li>Motor battery</li></ul>$t$,null,$t$Arduino sends signals. Driver supplies the power.$t$,1,8),
    (m,$t$Wire the drive system$t$,$t$<p><strong>🎯 Objective:</strong> Connect the motors, battery and control pins to the motor driver and Arduino.</p><h3>Steps</h3><ol><li>Mount the motor driver on the chassis and plug it firmly onto the Arduino so the pins line up.</li><li>Connect the motor battery to the driver's motor power terminal: 12V to the positive terminal and GND to the negative terminal.</li><li>Connect the 5V on the motor driver to the 5V on the Arduino. Use another wire to connect the GND of the driver to the GND of the Arduino.</li><li>Connect the two wires of a DC motor to the driver's motor outputs: OUT 1 and OUT 2 for one motor, OUT 3 and OUT 4 for the other. Repeat for the other two motors.</li><li>Use pin-to-port wires to connect the control pins: IN 1 to D8, IN 2 to D9, IN 3 to D10 and IN 4 to D11.</li><li>Connect the USB cable from your laptop to the Arduino.</li></ol><p><em>📷 Picture to be added: the motor driver wired to the Arduino and two motors</em></p><p><strong>⚠ Caution:</strong> Check the polarity: 12V goes to positive and GND to negative. Ask your teacher to check your wiring before you connect the USB cable.</p><p><strong>[[VERIFY: The client notes connect the motor driver to pins D8, D9, D10 and D11 (Lesson 3) and also connect the ultrasonic sensor TRIG to D11 and ECHO to D10 (Lesson 4). The same pins cannot do both jobs. Check the working car and correct the pin numbers in the lessons, the pin table and the quizzes.]]</strong></p><p><strong>[[VERIFY: The notes describe both a motor driver that plugs onto the Arduino and one wired with IN1 to IN4 jumper wires. Confirm which part the kit uses.]]</strong></p>$t$,null,$t$OUT 1 and OUT 2 run one motor. OUT 3 and OUT 4 run the other.$t$,2,20),
    (m,$t$Test the motors in mBlock$t$,$t$<p><strong>🎯 Objective:</strong> Write a simple program to spin a motor and check that it works.</p><p>For this first test you may connect only two motors, as your teacher directs.</p><h3>Steps</h3><ol><li>Open <strong>mBlock</strong> on your computer.</li><li>Your teacher will give you the code. Make a simple block program that turns Motor 1 <strong>on for 2 seconds</strong> and then <strong>off</strong>.</li><li>Upload the program to the Arduino.</li><li>Watch the result: the motor should spin for 2 seconds and then stop.</li><li>Repeat for the second motor.</li></ol><p><em>📷 Picture to be added: the mBlock program that runs a motor for 2 seconds</em></p><h3>If the motor does not spin</h3><ul><li>Check the power: is the battery connected the right way round?</li><li>Check the motor wires on the correct outputs.</li><li>Check the control wires on the correct pins.</li></ul>$t$,null,$t$Test one motor at a time.$t$,3,15);
