  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 4: The ultrasonic sensor$t$,$t$Give the robot "eyes" for obstacles by measuring distance with sound.$t$,4) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$How the ultrasonic sensor works$t$,$t$<p><strong>🎯 Objective:</strong> Explain how the sensor measures distance.</p><p>The ultrasonic sensor sends out a pulse of sound you cannot hear (<strong>TRIG</strong>). The sound bounces back from an object, and the sensor listens for it (<strong>ECHO</strong>). The time taken tells the Arduino how far away the object is.</p><table><thead><tr><th>Pin</th><th>Job</th></tr></thead><tbody><tr><td>VCC</td><td>Power (5V)</td></tr><tr><td>GND</td><td>Ground</td></tr><tr><td>TRIG</td><td>Sends the sound pulse</td></tr><tr><td>ECHO</td><td>Receives the reflected sound</td></tr></tbody></table><h3>You need</h3><ul><li>Ultrasonic sensor</li><li>Arduino Uno</li><li>Breadboard</li><li>8 pin-to-pin jumper wires</li><li>Chassis</li></ul>$t$,null,$t$TRIG sends. ECHO listens.$t$,1,8),
    (m,$t$Wire the ultrasonic sensor$t$,$t$<p><strong>🎯 Objective:</strong> Connect the sensor to the breadboard and the Arduino.</p><h3>Steps</h3><ol><li>Place the ultrasonic sensor on the breadboard so that each of its four pins has its own row.</li><li>Connect the sensor's <strong>VCC</strong> to the breadboard, then from the same row to <strong>5V</strong> on the Arduino.</li><li>Connect the sensor's <strong>GND</strong> to the breadboard, then from the same row to <strong>GND</strong> on the Arduino.</li><li>Connect the sensor's <strong>TRIG</strong> to the breadboard, then from the same row to <strong>D11</strong> on the Arduino.</li><li>Connect the sensor's <strong>ECHO</strong> to the breadboard, then from the same row to <strong>D10</strong> on the Arduino.</li><li>Mount the breadboard securely on the chassis.</li></ol><p><em>📷 Picture to be added: the ultrasonic sensor on the breadboard wired to the Arduino</em></p><p><strong>[[VERIFY: The client notes connect the motor driver to pins D8, D9, D10 and D11 (Lesson 3) and also connect the ultrasonic sensor TRIG to D11 and ECHO to D10 (Lesson 4). The same pins cannot do both jobs. Check the working car and correct the pin numbers in the lessons, the pin table and the quizzes.]]</strong></p>$t$,null,$t$Each sensor pin gets its own row on the breadboard.$t$,2,20),
    (m,$t$Test the sensor in mBlock$t$,$t$<p><strong>🎯 Objective:</strong> Read the distance on your computer screen.</p><h3>Steps</h3><ol><li>Connect the USB cable to the Arduino and the computer.</li><li>Open <strong>mBlock</strong> and load or create the distance-reading program your teacher gives you.</li><li>Place an object, like a book or your hand, in front of the sensor.</li><li>Move it closer and farther away. The reading on the screen should change.</li></ol>$t$,null,$t$Closer object = smaller number.$t$,3,12);
