  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$Scratch$t$,false,1),(qq,$t$Arduino IDE$t$,false,2),(qq,$t$mBlock$t$,true,3),(qq,$t$Fritzing$t$,false,4);
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 5: The water pump and relay module$t$,$t$Switch the water pump safely using a relay.$t$,5) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Why we use a relay$t$,$t$<p><strong>🎯 Objective:</strong> Explain why the pump is controlled through a relay.</p><p>The pump needs more power than an Arduino pin can give. A <strong>relay module</strong> works like a security gate. The Arduino sends a tiny signal to the relay's <strong>IN</strong> pin, and the relay switches the pump on or off safely.</p><h3>You need</h3><ul><li>DC water pump</li><li>Water tank</li><li>Relay module</li><li>Jumper wires</li></ul><p><strong>⚠ Caution:</strong> Keep water away from the Arduino, breadboard and wires. Place the tank and pump so they cannot spill onto the electronics, switch the power off before filling the tank, and wipe up any spills straight away.</p>$t$,null,$t$Relay = a gate the Arduino can open and close.$t$,1,8),
    (m,$t$Wire the pump through the relay$t$,$t$<p><strong>🎯 Objective:</strong> Connect the relay module to the Arduino and wire the pump through it.</p><h3>Steps</h3><ol><li>Place the relay module and pump near the breadboard and Arduino so the wires reach comfortably.</li><li>Connect the relay's <strong>VCC</strong> to the breadboard, then from the same row to <strong>5V</strong> on the Arduino.</li><li>Connect the relay's <strong>GND</strong> to the breadboard, then from the same row to <strong>GND</strong> on the Arduino.</li><li>Connect the relay's <strong>IN</strong> pin to <strong>D7</strong> on the Arduino.</li><li>Wire the pump through the relay: connect 5V to the <strong>COM</strong> (common) terminal of the relay.</li><li>Connect the pump's negative port (GND) to the GND of the Arduino.</li></ol><p><em>📷 Picture to be added: the relay module wired to the pump and the Arduino</em></p><p><strong>[[VERIFY: Lesson 9 refers to the relay's COM and NO terminals, but only COM is mentioned here. Confirm the full pump wiring (which relay terminal the pump connects to) and add it.]]</strong></p>$t$,null,$t$The Arduino's signal goes to IN. The pump is wired through COM.$t$,2,20),
    (m,$t$Test the pump$t$,$t$<p><strong>🎯 Objective:</strong> Upload a program to check that the pump works.</p><h3>Steps</h3><ol><li>Make sure the water tank has a little water and nothing can spill on the electronics.</li><li>Upload the test code your teacher gives you.</li><li>Watch and listen: the pump should switch on and off.</li></ol><p><strong>⚠ Caution:</strong> Keep water away from the Arduino, breadboard and wires. Place the tank and pump so they cannot spill onto the electronics, switch the power off before filling the tank, and wipe up any spills straight away.</p>$t$,null,$t$A program is needed to switch the relay.$t$,3,10);
