  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 6: The flame sensor$t$,$t$Connect the flame sensor and tune how sensitive it is.$t$,6) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$How the flame sensor works$t$,$t$<p><strong>🎯 Objective:</strong> Explain how the flame sensor detects fire.</p><p>The flame sensor senses the infrared (heat) light given off by a flame. When it sees a flame, its <strong>digital output</strong> pin sends a signal to the Arduino. The small <strong>potentiometer</strong> (a tiny turning screw) on the module adjusts how sensitive it is.</p><h3>You need</h3><ul><li>Flame sensor</li><li>Breadboard</li><li>Arduino Uno</li><li>Jumper wires</li></ul>$t$,null,$t$Potentiometer = sensitivity adjuster.$t$,1,8),
    (m,$t$Wire the flame sensor$t$,$t$<p><strong>🎯 Objective:</strong> Connect the flame sensor to the breadboard and the Arduino.</p><h3>Steps</h3><ol><li>Place the flame sensor on the breadboard so each pin sits in its own row.</li><li>Connect <strong>VCC</strong> to the breadboard, then from the same row to <strong>5V</strong> on the Arduino.</li><li>Connect <strong>GND</strong> to the breadboard, then from the same row to <strong>GND</strong> on the Arduino.</li><li>Connect the sensor's <strong>digital output</strong> to <strong>D2</strong> on the Arduino.</li></ol><p><em>📷 Picture to be added: the flame sensor wired to the Arduino</em></p>$t$,null,$t$Digital output goes to D2.$t$,2,15),
    (m,$t$Test and tune the sensor$t$,$t$<p><strong>🎯 Objective:</strong> Check that the sensor sees a flame and adjust its sensitivity.</p><h3>Steps</h3><ol><li>Upload the flame-sensor test code your teacher gives you.</li><li>With your teacher present, hold a small flame at a safe distance from the sensor.</li><li>Turn the small potentiometer slowly while testing until the sensor reacts at the right distance.</li></ol><p><strong>⚠ Caution:</strong> Fire is dangerous. Only test with a flame when your teacher is present, keep everyone at a safe distance, keep long hair and loose clothing away, and keep water or a fire blanket nearby. Never leave a flame unattended.</p>$t$,null,$t$Adjust the sensitivity while testing.$t$,3,12);
