  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 7: Designing and building the robotic car$t$,$t$Mount all the parts and connect the whole system.$t$,7) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Plan and mount the hardware$t$,$t$<p><strong>🎯 Objective:</strong> Mount every part on the chassis so wires can reach comfortably.</p><h3>You need</h3><ul><li>Flame sensor</li><li>DC water pump</li><li>Relay module</li><li>Batteries</li><li>Arduino Uno</li><li>Motor driver</li><li>Jumper wires</li><li>Ultrasonic sensor</li><li>Breadboard</li><li>Switch</li><li>4 DC motors</li><li>4 wheels</li><li>Water tank</li><li>Chassis</li></ul><p>Secure the Arduino, motor driver, relay, breadboard, pump, sensors and batteries to the chassis. Think about where each wire has to go before you stick anything down.</p><p><strong>⚠ Caution:</strong> Keep water away from the Arduino, breadboard and wires. Place the tank and pump so they cannot spill onto the electronics, switch the power off before filling the tank, and wipe up any spills straight away.</p>$t$,null,$t$Plan the layout first. Wires must reach.$t$,1,20),
    (m,$t$Wire the motors and the sensors$t$,$t$<p><strong>🎯 Objective:</strong> Connect the drive system, ultrasonic sensor and flame sensor.</p><h3>Steps</h3><ol><li>Plug the motor driver onto the Arduino. Connect the motor battery to the driver: 12V to positive and GND to negative.</li><li>Connect the motor wires: OUT 1 and OUT 2 for one motor, OUT 3 and OUT 4 for the other.</li><li>Wire the ultrasonic sensor on the breadboard: VCC to 5V, GND to GND, TRIG and ECHO to their pins.</li><li>Wire the flame sensor on the breadboard: VCC to 5V, GND to GND, digital output to D2.</li></ol><p><strong>[[VERIFY: The client notes connect the motor driver to pins D8, D9, D10 and D11 (Lesson 3) and also connect the ultrasonic sensor TRIG to D11 and ECHO to D10 (Lesson 4). The same pins cannot do both jobs. Check the working car and correct the pin numbers in the lessons, the pin table and the quizzes.]]</strong></p>$t$,null,$t$Do one part at a time and check it before the next.$t$,2,25),
    (m,$t$Wire the pump and add the main switch$t$,$t$<p><strong>🎯 Objective:</strong> Connect the relay and pump, then add the power switch.</p><h3>Steps</h3><ol><li>Connect the relay module: VCC to 5V, GND to GND and IN to D7.</li><li>Wire the pump through the relay: 5V to COM, and the pump's negative port to GND.</li><li>Place the switch on the main battery, or between the Arduino supply and the Arduino input.</li><li>Power the Arduino using the USB cable.</li></ol><h3>Pin summary</h3><table><thead><tr><th>Part</th><th>Connection</th></tr></thead><tbody><tr><td>Motor driver IN 1 to IN 4</td><td>D8, D9, D10, D11</td></tr><tr><td>Ultrasonic TRIG / ECHO</td><td>D11 / D10</td></tr><tr><td>Relay IN</td><td>D7</td></tr><tr><td>Flame sensor digital output</td><td>D2</td></tr></tbody></table><p><strong>[[VERIFY: The client notes connect the motor driver to pins D8, D9, D10 and D11 (Lesson 3) and also connect the ultrasonic sensor TRIG to D11 and ECHO to D10 (Lesson 4). The same pins cannot do both jobs. Check the working car and correct the pin numbers in the lessons, the pin table and the quizzes.]]</strong></p>$t$,null,$t$Relay IN = D7. Flame sensor = D2.$t$,3,15),
    (m,$t$Final connection check$t$,$t$<p><strong>🎯 Objective:</strong> Check every connection before you power the robot.</p><h3>Check yourself</h3><ul><li>Are all the power wires (5V and GND) on the correct pins?</li><li>Is the motor battery connected the right way round?</li><li>Does each sensor pin sit in its own breadboard row?</li><li>Is the water kept away from the electronics?</li><li>Has your teacher checked the wiring?</li></ul><p>Only power the robot once every answer is yes.</p>$t$,null,$t$Check twice, power once.$t$,4,10);
