  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 9: Troubleshooting and reflection$t$,$t$Find and fix common problems, then think about what you learned.$t$,9) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Troubleshooting: finding and fixing problems$t$,$t$<p><strong>🎯 Objective:</strong> Use basic troubleshooting steps to fix wiring and programming problems.</p><p>Sometimes, even when we follow every step, our system does not work as expected. <strong>Troubleshooting</strong> means finding and fixing problems in an organised way, one thing at a time.</p><h3>If the pump does not respond</h3><ul><li>Check the relay wiring (COM and NO).</li><li>Check that the relay IN pin matches the pin used in your mBlock program.</li><li>Check the USB cable is connected properly.</li><li>Upload the program again.</li><li>Check that the Arduino power light is on.</li></ul><h3>If the sensor gives wrong readings</h3><ul><li>Check that the ultrasonic sensor is facing the right direction.</li><li>Make sure nothing is blocking the signal or too close to it.</li><li>Check that the ECHO and TRIG wires are not swapped.</li></ul><h3>If mBlock shows a connection error</h3><ul><li>Disconnect and reconnect the USB cable.</li><li>Click <strong>Connect</strong> again under Devices.</li><li>Restart mBlock if the board is still not recognised.</li></ul>$t$,null,$t$Change one thing at a time, then test again.$t$,1,15),
    (m,$t$Reflection$t$,$t$<p><strong>🎯 Objective:</strong> Think about what you learned and how the system could be improved.</p><p>Discuss these questions with your group:</p><ul><li>What controls the fire extinguisher robotic car in this program?</li><li>What happens when the distances change?</li><li>How could this system be used at home or at school?</li><li>What was the most challenging part of setting up your system?</li><li>What new skill did you learn?</li><li>How could you improve the robot?</li></ul>$t$,null,$t$Mistakes you fixed are the best lessons.$t$,2,15);
