  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 10: Presenting the robot$t$,$t$Present your robot, explain how it works and reflect on your project.$t$,10) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Prepare your presentation$t$,$t$<p><strong>🎯 Objective:</strong> Get ready to present your fire extinguisher robotic car.</p><h3>You need</h3><ul><li>Your completed fire extinguisher robotic car</li><li>A laptop</li><li>A project display table</li></ul><p>Each group will show its robot and explain how it works. Remember to describe what each part does and how the program controls the car automatically.</p><h3>Your presentation should</h3><ol><li>Introduce your project: group members and project title.</li><li>Show your model and describe how you designed it.</li><li>Explain the program briefly and say how the Arduino, ultrasonic sensor and flame sensor work together.</li></ol>$t$,null,$t$Speak clearly, work as a team, and use the model to explain.$t$,1,20),
    (m,$t$Presentation day$t$,$t$<p><strong>🎯 Objective:</strong> Present your robot confidently and give kind feedback to others.</p><ul><li>Speak clearly and confidently.</li><li>Work as a team: everyone should take part.</li><li>Use the model to support your explanation.</li><li>Listen to other groups and give one kind, helpful comment.</li></ul><h3>Check yourself</h3><ul><li>Did every team member speak?</li><li>Did you explain what each sensor does?</li><li>Did you show how the program controls the car?</li></ul>$t$,null,$t$Everyone in the team speaks.$t$,2,20);
