-- ===== Project: Automatic Fire Extinguisher Robotic Car (fire-extinguisher-robotic-car) =====
do $seed$
declare c uuid; m uuid; q uuid; qq uuid;
begin
  if exists (select 1 from courses where slug = 'fire-extinguisher-robotic-car') then
    raise notice 'Skipped: course "fire-extinguisher-robotic-car" already exists (nothing was changed).'; return;
  end if;
    values ($t$Project: Automatic Fire Extinguisher Robotic Car$t$,'fire-extinguisher-robotic-car',$t$Build a robot car that detects fire with a flame sensor, avoids obstacles with an ultrasonic sensor and puts the fire out with a water pump. Ten lessons from components to presentation.$t$,'intermediate',false,31,10,422) returning id into c;
end $seed$;
